ALTER TABLE "get_started_claims" DROP CONSTRAINT "get_started_quest_check";--> statement-breakpoint
ALTER TABLE "get_started_claims" DROP CONSTRAINT "get_started_slot_check";--> statement-breakpoint
ALTER TABLE "get_started_claims" DROP CONSTRAINT "get_started_amount_check";--> statement-breakpoint
ALTER TABLE "get_started_claims" ADD CONSTRAINT "get_started_quest_check" CHECK ("get_started_claims"."quest_key" IN ('connector', 'slack', 'imessage', 'workflow', 'invite', 'share', 'checkin'));--> statement-breakpoint
ALTER TABLE "get_started_claims" ADD CONSTRAINT "get_started_slot_check" CHECK (("get_started_claims"."status" <> 'granted' AND "get_started_claims"."reward_slot" IS NULL) OR ("get_started_claims"."status" = 'granted' AND (("get_started_claims"."quest_key" = 'invite' AND "get_started_claims"."reward_slot" BETWEEN 1 AND 15 AND "get_started_claims"."reward_slot" IS NOT NULL) OR ("get_started_claims"."quest_key" IN ('imessage', 'workflow', 'share') AND "get_started_claims"."reward_slot" = 1 AND "get_started_claims"."reward_slot" IS NOT NULL) OR ("get_started_claims"."quest_key" IN ('connector', 'slack', 'checkin') AND "get_started_claims"."reward_slot" IS NULL))));--> statement-breakpoint
ALTER TABLE "get_started_claims" ADD CONSTRAINT "get_started_amount_check" CHECK ("get_started_claims"."reward_amount" = CASE "get_started_claims"."quest_key" WHEN 'slack' THEN 2000 WHEN 'share' THEN 2000 WHEN 'imessage' THEN 1000 WHEN 'workflow' THEN 1000 ELSE 100 END);